"""Public artifact integrity/resume tests with generated bytes, never datasets."""
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from threading import Thread
from contextlib import contextmanager
import hashlib,re,sys
from pathlib import Path
import pytest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from scripts.download_chunks import fetch

PAYLOAD=bytes(range(256))*5000


@contextmanager
def server(ignore_range=False):
    requested=[]
    class Handler(BaseHTTPRequestHandler):
        def log_message(self,*args):pass
        def do_GET(self):
            m=re.fullmatch(r'bytes=(\d+)-(\d+)',self.headers.get('Range',''))
            start,end=map(int,m.groups());requested.append((start,end))
            self.send_response(200 if ignore_range else 206)
            self.send_header('Content-Range',f'bytes {start}-{end}/{len(PAYLOAD)}')
            self.send_header('Content-Length',str(end-start+1));self.end_headers()
            try:self.wfile.write(PAYLOAD[start:end+1])
            except (BrokenPipeError,ConnectionResetError):pass
    s=ThreadingHTTPServer(('127.0.0.1',0),Handler);thread=Thread(target=s.serve_forever,daemon=True);thread.start()
    try:yield f'http://127.0.0.1:{s.server_port}/artifact',requested
    finally:s.shutdown();s.server_close();thread.join()


def test_resume_keeps_verified_prefix_and_hashes_whole_artifact(tmp_path):
    path=tmp_path/'partial';prefix=12345;path.write_bytes(PAYLOAD[:prefix])
    with server() as (url,requested):
        fetch(url,path,len(PAYLOAD),hashlib.sha256(PAYLOAD).hexdigest(),chunk_bytes=65536,budget_sec=10)
    assert path.read_bytes()==PAYLOAD
    assert min(start for start,_ in requested)==prefix
    assert all(start>=prefix for start,_ in requested)


def test_rejects_non_partial_response_before_appending(tmp_path):
    path=tmp_path/'partial';path.write_bytes(PAYLOAD[:123])
    with server(ignore_range=True) as (url,_):
        with pytest.raises(ValueError,match='exact bounded range'):
            fetch(url,path,len(PAYLOAD),hashlib.sha256(PAYLOAD).hexdigest(),chunk_bytes=65536,budget_sec=10)
    assert path.read_bytes()==PAYLOAD[:123]


def test_rejects_completed_corrupt_file_without_network(tmp_path):
    path=tmp_path/'partial';path.write_bytes(b'bad')
    with pytest.raises(ValueError,match='SHA256 mismatch'):
        fetch('http://unused.invalid/',path,3,hashlib.sha256(b'yes').hexdigest())
